window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-20e83140f07a5662"]={"versions": [{"id": "FIG-20e83140f07a5662", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur funktionalen Ablaufbeschreibung innerhalb des E2E-Profils 7 (AUTOSAR PRS E2E Protocol). Das Diagramm spezifiziert den Teilschritt „Compute offset“ für die drei zentralen Profilfunktionen <code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code> und <code>E2E_P07Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontexte (Aufrufer/Aktivitäten)</strong>: Drei lose referenzierte Funktionsknoten <code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code> und <code>E2E_P07Forward()</code>.\n</li><li><strong>Eingangsparameter / Konfigurationsstruktur</strong>: <code>Config-&gt;Offset</code> (Offset-Angabe aus der E2E-Konfigurationsstruktur).\n</li><li><strong>Aktion / Rechenschritt</strong>: <code>Offset = Config-&gt;Offset / 8</code>.\n</li><li><strong>Lokale Variable</strong>: <code>Offset</code> vom Datentyp <code>uint32</code> (repräsentiert den berechneten Byte-Offset).\n</li><li><strong>Ablauf-Elemente</strong>: Initialknoten (Startknoten), Aktionszustand, Aktivitätsendknoten (Final State) sowie eine erklärende Notiz.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf startet am Initialknoten.\n</li><li>Der Kontrollfluss geht direkt in die Aktion <code>Offset = Config-&gt;Offset / 8</code> über.\n</li><li>Dabei wird der in Bit konfigurierte Wert <code>Config-&gt;Offset</code> durch 8 geteilt, um die lokale Variable <code>Offset</code> in Byte zu ermitteln.\n</li><li>Nach Ausführung der Zuweisung wird der Kontrollfluss zum Aktivitätsendknoten weitergeleitet und der Schritt ist beendet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Berechnungsschritt ist normativ verbindlich für die Implementierung der Funktionen <code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code> und <code>E2E_P07Forward()</code> gemäß Vorgabe <code>[PRS_E2E_00488]</code>.\n</li><li>Der konfigurierte Bit-Offset (<code>Config-&gt;Offset</code>) muss durch ganzzahlige Division durch 8 in einen Byte-Offset konvertiert und als lokale Variable vom Typ <code>uint32</code> bereitgestellt werden.\n</li><li>Die Zuweisung setzt voraus, dass der Offset ein Vielfaches von 8 Bits darstellt bzw. die E2E-Header-Positionierung auf Byte-Grenzen ausgerichtet ist.\n</li></ul>"}, {"id": "FIG-f867a18a527c2914", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur funktionalen Ablaufbeschreibung innerhalb des E2E-Profils 7 (AUTOSAR PRS E2E Protocol). Das Diagramm spezifiziert den Teilschritt „Compute offset“ für die drei zentralen Profilfunktionen <code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code> und <code>E2E_P07Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontexte (Aufrufer/Aktivitäten)</strong>: Drei lose referenzierte Funktionsknoten <code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code> und <code>E2E_P07Forward()</code>.\n</li><li><strong>Eingangsparameter / Konfigurationsstruktur</strong>: <code>Config-&gt;Offset</code> (Offset-Angabe aus der E2E-Konfigurationsstruktur).\n</li><li><strong>Aktion / Rechenschritt</strong>: <code>Offset = Config-&gt;Offset / 8</code>.\n</li><li><strong>Lokale Variable</strong>: <code>Offset</code> vom Datentyp <code>uint32</code> (repräsentiert den berechneten Byte-Offset).\n</li><li><strong>Ablauf-Elemente</strong>: Initialknoten (Startknoten), Aktionszustand, Aktivitätsendknoten (Final State) sowie eine erklärende Notiz.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf startet am Initialknoten.\n</li><li>Der Kontrollfluss geht direkt in die Aktion <code>Offset = Config-&gt;Offset / 8</code> über.\n</li><li>Dabei wird der in Bit konfigurierte Wert <code>Config-&gt;Offset</code> durch 8 geteilt, um die lokale Variable <code>Offset</code> in Byte zu ermitteln.\n</li><li>Nach Ausführung der Zuweisung wird der Kontrollfluss zum Aktivitätsendknoten weitergeleitet und der Schritt ist beendet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Berechnungsschritt ist normativ verbindlich für die Implementierung der Funktionen <code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code> und <code>E2E_P07Forward()</code> gemäß Vorgabe <code>[PRS_E2E_00488]</code>.\n</li><li>Der konfigurierte Bit-Offset (<code>Config-&gt;Offset</code>) muss durch ganzzahlige Division durch 8 in einen Byte-Offset konvertiert und als lokale Variable vom Typ <code>uint32</code> bereitgestellt werden.\n</li><li>Die Zuweisung setzt voraus, dass der Offset ein Vielfaches von 8 Bits darstellt bzw. die E2E-Header-Positionierung auf Byte-Grenzen ausgerichtet ist.\n</li></ul>"}], "trans": [{"from": "FIG-20e83140f07a5662", "to": "FIG-f867a18a527c2914", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
